python -c "
import pypdf

reader = pypdf.PdfReader('SistemasDistribuidos/george-coulouris-distributed-systems-concepts-and-design-5th-edition-2.pdf')

pages_found = {}
sections = ['16.3', '16.4', '16.5', '16.6']

for idx, page in enumerate(reader.pages):
    text = page.extract_text()
    for sec in sections:
        if sec in text:
            if sec not in pages_found:
                pages_found[sec] = []
            pages_found[sec].append(idx + 1)

for sec, pgs in pages_found.items():
    print(f'Section {sec}: pages {pgs[:10]}')
"

