with open('16_4_final.txt', 'r', encoding='utf-8') as f:
    text = f.read()

import re

# find lines that look like headings or subheadings
for line in text.split('\n'):
    line_s = line.strip()
    if re.match(r'^(16\.\d+|[A-Z][a-z A-Z0-9\-\(\)]+)$', line_s) and len(line_s) < 60:
        print('HEAD:', line_s)
    elif line_s.endswith('  ') or 'Figure 16.' in line_s or 'Lock' in line_s or 'Deadlock' in line_s:
        if len(line_s) < 70 and not line_s.startswith('the') and not line_s.startswith('and'):
            print('   SUB:', line_s)
"

